def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform divider that leaves matching-sized panels on either side.
    split = None
    for r in range(h):
        if r == h - r - 1 and len(set(grid[r])) == 1:
            split = ("row", r)
            break
    if split is None:
        for c in range(w):
            if c == w - c - 1 and all(grid[r][c] == grid[0][c] for r in range(h)):
                split = ("col", c)
                break

    if split[0] == "row":
        r = split[1]
        first, second = grid[:r], grid[r + 1:]
    else:
        c = split[1]
        first = [row[:c] for row in grid]
        second = [row[c + 1:] for row in grid]

    shared = set(x for row in first for x in row) & set(x for row in second for x in row)
    from collections import Counter
    counts = Counter(x for row in first + second for x in row if x in shared)
    background = counts.most_common(1)[0][0]

    return [[3 if a == b else background for a, b in zip(row_a, row_b)]
            for row_a, row_b in zip(first, second)]
